#include "analyzer.h"
#include <string.h>
#include "memory.h"
#if defined(__GNUC__)
#pragma GCC diagnostic ignored "-Wswitch"
#endif
typedef enum { SYMBOL_VARIABLE, SYMBOL_CONSTANT, SYMBOL_PARAMETER, SYMBOL_FUNCTION, SYMBOL_ITERATOR } SymbolKind;
typedef struct {char *name;size_t length;SymbolKind kind;SourceSpan span;size_t reads,writes;bool pending_write;} Symbol;
typedef struct Scope {struct Scope *parent;Symbol *symbols;size_t count,capacity;} Scope;
typedef struct {AnalysisResult *result;Scope *scope;size_t uncertain_depth;} Analyzer;
static const char *native_names[]={"escreva","leia","texto","inteiro","decimal","tipo","tamanho","adicione","remova"};
void analysis_result_init(AnalysisResult *r){if(r!=NULL)memset(r,0,sizeof(*r));}
void analysis_result_free(AnalysisResult *r){size_t i;if(r==NULL)return;for(i=0U;i<r->count;i++){memory_free(r->diagnostics[i].name);memory_free(r->diagnostics[i].suggestion);}memory_free(r->diagnostics);analysis_result_init(r);}
static bool report(Analyzer *a,AnalysisSeverity severity,AnalysisCode code,SourceSpan span,const char *name,size_t length,const char *suggestion,size_t suggestion_length,bool boolean_value){AnalysisDiagnostic *grown,*d;size_t capacity;if(a->result->count==a->result->capacity){if(!memory_grow_capacity(a->result->capacity,a->result->count+1U,&capacity))return false;grown=memory_reallocate_array(a->result->diagnostics,capacity,sizeof(*grown));if(grown==NULL)return false;a->result->diagnostics=grown;a->result->capacity=capacity;}d=&a->result->diagnostics[a->result->count++];memset(d,0,sizeof(*d));d->severity=severity;d->code=code;d->span=span;d->boolean_value=boolean_value;if(name!=NULL){d->name=memory_copy_string(name,length);if(d->name==NULL)return false;d->name_length=length;}if(suggestion!=NULL){d->suggestion=memory_copy_string(suggestion,suggestion_length);if(d->suggestion==NULL)return false;d->suggestion_length=suggestion_length;}if(severity==ANALYSIS_ERROR)a->result->errors++;else if(severity==ANALYSIS_WARNING)a->result->warnings++;else a->result->information++;return true;}
static void scope_init(Scope *s,Scope *parent){s->parent=parent;s->symbols=NULL;s->count=0U;s->capacity=0U;}
static Symbol *find_current(Scope *s,const char *name,size_t length){size_t i;for(i=0U;i<s->count;i++)if(s->symbols[i].length==length&&memcmp(s->symbols[i].name,name,length)==0)return &s->symbols[i];return NULL;}
static Symbol *find_symbol(Scope *s,const char *name,size_t length){while(s!=NULL){Symbol *symbol=find_current(s,name,length);if(symbol!=NULL)return symbol;s=s->parent;}return NULL;}
static bool is_native(const char *name,size_t length){size_t i;for(i=0U;i<sizeof(native_names)/sizeof(native_names[0]);i++)if(strlen(native_names[i])==length&&memcmp(native_names[i],name,length)==0)return true;return false;}
static bool add_symbol(Analyzer *a,const char *name,size_t length,SymbolKind kind,SourceSpan span,Symbol **out){Symbol *grown,*s,*outer;size_t capacity;if(find_current(a->scope,name,length)!=NULL){*out=find_current(a->scope,name,length);return true;}outer=a->scope->parent==NULL?NULL:find_symbol(a->scope->parent,name,length);if(outer!=NULL&&!report(a,ANALYSIS_WARNING,ANALYSIS_SHADOWING,span,name,length,NULL,0U,false))return false;if(outer==NULL&&a->scope->parent!=NULL&&is_native(name,length)&&!report(a,ANALYSIS_WARNING,ANALYSIS_NATIVE_SHADOWING,span,name,length,NULL,0U,false))return false;if(a->scope->count==a->scope->capacity){if(!memory_grow_capacity(a->scope->capacity,a->scope->count+1U,&capacity))return false;grown=memory_reallocate_array(a->scope->symbols,capacity,sizeof(*grown));if(grown==NULL)return false;a->scope->symbols=grown;a->scope->capacity=capacity;}s=&a->scope->symbols[a->scope->count++];memset(s,0,sizeof(*s));s->name=memory_copy_string(name,length);if(s->name==NULL)return false;s->length=length;s->kind=kind;s->span=span;s->pending_write=kind!=SYMBOL_FUNCTION;*out=s;return true;}
static AnalysisCode unused_code(SymbolKind kind){switch(kind){case SYMBOL_VARIABLE:return ANALYSIS_UNUSED_VARIABLE;case SYMBOL_CONSTANT:return ANALYSIS_UNUSED_CONSTANT;case SYMBOL_PARAMETER:return ANALYSIS_UNUSED_PARAMETER;case SYMBOL_FUNCTION:return ANALYSIS_UNUSED_FUNCTION;case SYMBOL_ITERATOR:return ANALYSIS_UNUSED_ITERATOR;}return ANALYSIS_UNUSED_VARIABLE;}
static bool finish_scope(Analyzer *a,Scope *s){size_t i;bool ok=true;for(i=0U;i<s->count;i++){Symbol *symbol=&s->symbols[i];if(symbol->reads==0U){AnalysisCode code=(symbol->kind==SYMBOL_VARIABLE&&symbol->writes>0U)?ANALYSIS_ONLY_ASSIGNED:unused_code(symbol->kind);AnalysisSeverity severity=symbol->kind==SYMBOL_ITERATOR?ANALYSIS_INFORMATION:ANALYSIS_WARNING;if(!report(a,severity,code,symbol->span,symbol->name,symbol->length,NULL,0U,false))ok=false;}memory_free(symbol->name);}memory_free(s->symbols);return ok;}
static size_t edit_distance_limited(const char *a,size_t alen,const char *b,size_t blen){size_t prev[65],curr[65],i,j;if(alen>64U||blen>64U||alen>blen+2U||blen>alen+2U)return 3U;for(j=0U;j<=blen;j++)prev[j]=j;for(i=1U;i<=alen;i++){curr[0]=i;for(j=1U;j<=blen;j++){size_t sub=prev[j-1U]+(a[i-1U]==b[j-1U]?0U:1U),del=prev[j]+1U,ins=curr[j-1U]+1U;curr[j]=sub<del?sub:del;if(ins<curr[j])curr[j]=ins;}for(j=0U;j<=blen;j++)prev[j]=curr[j];}return prev[blen];}
static Symbol *closest_symbol(Scope *scope,const char *name,size_t length){Symbol *best=NULL;size_t best_distance=3U;while(scope!=NULL){size_t i;for(i=0U;i<scope->count;i++){size_t distance=edit_distance_limited(name,length,scope->symbols[i].name,scope->symbols[i].length);if(distance<best_distance){best=&scope->symbols[i];best_distance=distance;}}scope=scope->parent;}return best_distance<=2U?best:NULL;}
static bool analyze_expr(Analyzer *,const Expr *);
static bool read_name(Analyzer *a,const char *name,size_t length,SourceSpan span){Symbol *symbol=find_symbol(a->scope,name,length);if(symbol!=NULL){symbol->reads++;symbol->pending_write=false;return true;}if(is_native(name,length))return true;{Symbol *close=closest_symbol(a->scope,name,length);return report(a,ANALYSIS_ERROR,ANALYSIS_UNDEFINED_NAME,span,name,length,close==NULL?NULL:close->name,close==NULL?0U:close->length,false);}}
static bool analyze_expr(Analyzer *a,const Expr *e){size_t i;if(e==NULL)return true;switch(e->type){case EXPR_LITERAL:return true;case EXPR_IDENTIFIER:return read_name(a,e->as.identifier.name,e->as.identifier.length,e->span);case EXPR_UNARY:return analyze_expr(a,e->as.unary.operand);case EXPR_BINARY:return analyze_expr(a,e->as.binary.left)&&analyze_expr(a,e->as.binary.right);case EXPR_GROUPING:return analyze_expr(a,e->as.grouping.expression);case EXPR_CALL:if(!analyze_expr(a,e->as.call.callee))return false;for(i=0U;i<e->as.call.argument_count;i++)if(!analyze_expr(a,e->as.call.arguments[i]))return false;return true;case EXPR_LIST:a->result->metrics.lists++;for(i=0U;i<e->as.list.count;i++)if(!analyze_expr(a,e->as.list.elements[i]))return false;return true;case EXPR_INDEX:return analyze_expr(a,e->as.index.target)&&analyze_expr(a,e->as.index.index);case EXPR_MEMBER:return analyze_expr(a,e->as.member.target);}return true;}
static bool constant_bool(const Expr *e,bool *value){if(e==NULL)return false;if(e->type==EXPR_GROUPING)return constant_bool(e->as.grouping.expression,value);if(e->type==EXPR_LITERAL&&e->as.literal.type==VALUE_BOOLEAN){*value=e->as.literal.as.boolean;return true;}if(e->type==EXPR_UNARY&&e->as.unary.operator_type==UNARY_NOT&&constant_bool(e->as.unary.operand,value)){*value=!*value;return true;}if(e->type==EXPR_BINARY&&e->as.binary.left->type==EXPR_LITERAL&&e->as.binary.right->type==EXPR_LITERAL){const Value *l=&e->as.binary.left->as.literal,*r=&e->as.binary.right->as.literal;if((l->type==VALUE_INTEGER||l->type==VALUE_DECIMAL)&&(r->type==VALUE_INTEGER||r->type==VALUE_DECIMAL)){double x=l->type==VALUE_INTEGER?(double)l->as.integer:l->as.decimal,y=r->type==VALUE_INTEGER?(double)r->as.integer:r->as.decimal;switch(e->as.binary.operator_type){case BINARY_LESS:*value=x<y;return true;case BINARY_LESS_EQUAL:*value=x<=y;return true;case BINARY_GREATER:*value=x>y;return true;case BINARY_GREATER_EQUAL:*value=x>=y;return true;case BINARY_EQUAL:*value=x==y;return true;case BINARY_NOT_EQUAL:*value=x!=y;return true;default:break;}}}return false;}
static bool analyze_array(Analyzer *,const StmtArray *,bool *);
static bool analyze_block(Analyzer *a,const Stmt *block,bool *returns){Scope child;Scope *previous=a->scope;bool ok;scope_init(&child,previous);a->scope=&child;ok=analyze_array(a,&block->as.block.statements,returns);a->scope=previous;if(!finish_scope(a,&child))ok=false;return ok;}
static bool analyze_stmt(Analyzer *a,const Stmt *s,bool *returns){bool condition,then_returns=false,else_returns=false;size_t i;*returns=false;if(s->type==STMT_FOR_EACH){Scope loop;Scope *previous=a->scope;Symbol *iterator;a->result->metrics.for_loops++;if(!analyze_expr(a,s->as.for_each_statement.iterable))return false;scope_init(&loop,previous);a->scope=&loop;if(!add_symbol(a,s->as.for_each_statement.iterator_name,s->as.for_each_statement.iterator_length,SYMBOL_ITERATOR,s->as.for_each_statement.iterator_span,&iterator)){a->scope=previous;return false;}a->uncertain_depth++;if(!analyze_stmt(a,s->as.for_each_statement.body,&then_returns)){a->uncertain_depth--;a->scope=previous;(void)finish_scope(a,&loop);return false;}a->uncertain_depth--;a->scope=previous;return finish_scope(a,&loop);}if(s->type==STMT_BREAK||s->type==STMT_CONTINUE)return true;switch(s->type){case STMT_EXPRESSION:return analyze_expr(a,s->as.expression.expression);case STMT_VARIABLE_DECLARATION:case STMT_CONSTANT_DECLARATION:{Symbol *symbol;if(!analyze_expr(a,s->as.declaration.initializer))return false;if(!add_symbol(a,s->as.declaration.name,s->as.declaration.name_length,s->type==STMT_VARIABLE_DECLARATION?SYMBOL_VARIABLE:SYMBOL_CONSTANT,s->as.declaration.name_span,&symbol))return false;if(s->type==STMT_VARIABLE_DECLARATION)a->result->metrics.variables++;else a->result->metrics.constants++;return true;}case STMT_ASSIGNMENT:{Symbol *symbol;if(!analyze_expr(a,s->as.assignment.value))return false;symbol=find_symbol(a->scope,s->as.assignment.name,s->as.assignment.name_length);if(symbol==NULL)return read_name(a,s->as.assignment.name,s->as.assignment.name_length,s->as.assignment.name_span);if(s->as.assignment.value->type==EXPR_IDENTIFIER&&s->as.assignment.value->as.identifier.length==symbol->length&&memcmp(s->as.assignment.value->as.identifier.name,symbol->name,symbol->length)==0)if(!report(a,ANALYSIS_INFORMATION,ANALYSIS_SELF_ASSIGNMENT,s->span,symbol->name,symbol->length,NULL,0U,false))return false;if(a->uncertain_depth==0U&&symbol->pending_write&&symbol->reads>0U&& !report(a,ANALYSIS_WARNING,ANALYSIS_OVERWRITTEN_VALUE,symbol->span,symbol->name,symbol->length,NULL,0U,false))return false;symbol->writes++;symbol->pending_write=true;return true;}case STMT_BLOCK:return analyze_block(a,s,returns);case STMT_IF:a->result->metrics.conditions++;if(!analyze_expr(a,s->as.if_statement.condition))return false;if(constant_bool(s->as.if_statement.condition,&condition)&&!report(a,ANALYSIS_WARNING,ANALYSIS_CONSTANT_CONDITION,s->as.if_statement.condition->span,NULL,0U,NULL,0U,condition))return false;a->uncertain_depth++;if(!analyze_stmt(a,s->as.if_statement.then_branch,&then_returns)){a->uncertain_depth--;return false;}if(s->as.if_statement.else_branch!=NULL&&!analyze_stmt(a,s->as.if_statement.else_branch,&else_returns)){a->uncertain_depth--;return false;}a->uncertain_depth--;*returns=s->as.if_statement.else_branch!=NULL&&then_returns&&else_returns;return true;case STMT_WHILE:a->result->metrics.while_loops++;if(!analyze_expr(a,s->as.while_statement.condition))return false;if(constant_bool(s->as.while_statement.condition,&condition)&&!report(a,condition?ANALYSIS_INFORMATION:ANALYSIS_WARNING,ANALYSIS_CONSTANT_CONDITION,s->as.while_statement.condition->span,NULL,0U,NULL,0U,condition))return false;a->uncertain_depth++;if(!analyze_stmt(a,s->as.while_statement.body,&then_returns)){a->uncertain_depth--;return false;}a->uncertain_depth--;return true;case STMT_FOR:{Scope loop;Scope *previous=a->scope;Symbol *iterator;int64_t start,end;a->result->metrics.for_loops++;if(!analyze_expr(a,s->as.for_statement.start)||!analyze_expr(a,s->as.for_statement.end))return false;if(s->as.for_statement.start->type==EXPR_LITERAL&&s->as.for_statement.start->as.literal.type==VALUE_INTEGER&&s->as.for_statement.end->type==EXPR_LITERAL&&s->as.for_statement.end->as.literal.type==VALUE_INTEGER){start=s->as.for_statement.start->as.literal.as.integer;end=s->as.for_statement.end->as.literal.as.integer;if(start>end&&!report(a,ANALYSIS_WARNING,ANALYSIS_EMPTY_FOR,s->span,s->as.for_statement.iterator_name,s->as.for_statement.iterator_length,NULL,0U,false))return false;}scope_init(&loop,previous);a->scope=&loop;if(!add_symbol(a,s->as.for_statement.iterator_name,s->as.for_statement.iterator_length,SYMBOL_ITERATOR,s->as.for_statement.iterator_span,&iterator)){a->scope=previous;return false;}a->uncertain_depth++;if(!analyze_stmt(a,s->as.for_statement.body,&then_returns)){a->uncertain_depth--;a->scope=previous;(void)finish_scope(a,&loop);return false;}a->uncertain_depth--;a->scope=previous;return finish_scope(a,&loop);}case STMT_FUNCTION:{Scope function_scope;Scope *previous=a->scope;Symbol *parameter;a->result->metrics.functions++;scope_init(&function_scope,previous);a->scope=&function_scope;for(i=0U;i<s->as.function.parameter_count;i++)if(!add_symbol(a,s->as.function.parameters[i],s->as.function.parameter_lengths[i],SYMBOL_PARAMETER,s->as.function.parameter_spans[i],&parameter)){a->scope=previous;return false;}if(!analyze_array(a,&s->as.function.body->as.block.statements,&then_returns)){a->scope=previous;(void)finish_scope(a,&function_scope);return false;}a->scope=previous;return finish_scope(a,&function_scope);}case STMT_RETURN:if(!analyze_expr(a,s->as.return_statement.value))return false;*returns=true;return true;case STMT_INDEX_ASSIGNMENT:return analyze_expr(a,s->as.index_assignment.target)&&analyze_expr(a,s->as.index_assignment.index)&&analyze_expr(a,s->as.index_assignment.value);}return true;}
static bool predeclare_functions(Analyzer *a,const StmtArray *array){size_t i;for(i=0U;i<array->count;i++){const Stmt *s=array->data[i];if(s->type==STMT_FUNCTION){Symbol *symbol;if(!add_symbol(a,s->as.function.name,s->as.function.name_length,SYMBOL_FUNCTION,s->as.function.name_span,&symbol))return false;}else if(s->type==STMT_IMPORT){Symbol *symbol;if(!add_symbol(a,s->as.import.binding,s->as.import.binding_length,SYMBOL_CONSTANT,s->as.import.path_span,&symbol))return false;}}return true;}
static bool analyze_array(Analyzer *a,const StmtArray *array,bool *returns){size_t i;bool unreachable=false,direct_return=false;if(!predeclare_functions(a,array))return false;for(i=0U;i<array->count;i++){const Stmt *current=array->data[i];if(unreachable&&!report(a,ANALYSIS_WARNING,ANALYSIS_UNREACHABLE,current->span,NULL,0U,NULL,0U,false))return false;if(i>0U&&a->uncertain_depth==0U&&current->type==STMT_ASSIGNMENT){const Stmt *previous=array->data[i-1U];if((previous->type==STMT_VARIABLE_DECLARATION||previous->type==STMT_CONSTANT_DECLARATION)&&previous->as.declaration.name_length==current->as.assignment.name_length&&memcmp(previous->as.declaration.name,current->as.assignment.name,current->as.assignment.name_length)==0)if(!report(a,ANALYSIS_WARNING,ANALYSIS_OVERWRITTEN_VALUE,previous->as.declaration.name_span,previous->as.declaration.name,previous->as.declaration.name_length,NULL,0U,false))return false;}if(!analyze_stmt(a,current,&direct_return))return false;if(direct_return)unreachable=true;}*returns=unreachable;return true;}
bool analyzer_analyze(const Program *program,AnalysisResult *result){Analyzer analyzer;Scope global;bool returns=false,ok;if(program==NULL||result==NULL)return false;scope_init(&global,NULL);analyzer.result=result;analyzer.scope=&global;analyzer.uncertain_depth=0U;ok=analyze_array(&analyzer,&program->statements,&returns);if(!finish_scope(&analyzer,&global))ok=false;return ok;}
static const char *severity_name(AnalysisSeverity s){return s==ANALYSIS_ERROR?"Erro":s==ANALYSIS_WARNING?"Aviso":"Informacao";}
static const char *category_name(AnalysisCode code){switch(code){case ANALYSIS_UNUSED_VARIABLE:case ANALYSIS_UNUSED_CONSTANT:case ANALYSIS_UNUSED_PARAMETER:case ANALYSIS_UNUSED_FUNCTION:case ANALYSIS_UNUSED_ITERATOR:case ANALYSIS_ONLY_ASSIGNED:case ANALYSIS_OVERWRITTEN_VALUE:case ANALYSIS_SELF_ASSIGNMENT:return "de simbolo";case ANALYSIS_UNREACHABLE:case ANALYSIS_CONSTANT_CONDITION:case ANALYSIS_EMPTY_FOR:return "de fluxo";case ANALYSIS_SHADOWING:case ANALYSIS_NATIVE_SHADOWING:return "de sombreamento";case ANALYSIS_UNDEFINED_NAME:return "de nome";}return "educacional";}
static void message(FILE *out,const AnalysisDiagnostic *d){switch(d->code){case ANALYSIS_UNUSED_VARIABLE:fprintf(out,"A variavel '%.*s' foi declarada, mas nunca utilizada.",(int)d->name_length,d->name);break;case ANALYSIS_UNUSED_CONSTANT:fprintf(out,"A constante '%.*s' foi declarada, mas nunca utilizada.",(int)d->name_length,d->name);break;case ANALYSIS_UNUSED_PARAMETER:fprintf(out,"O parametro '%.*s' nunca e utilizado.",(int)d->name_length,d->name);break;case ANALYSIS_UNUSED_FUNCTION:fprintf(out,"A funcao '%.*s' nunca e referenciada.",(int)d->name_length,d->name);break;case ANALYSIS_UNUSED_ITERATOR:fprintf(out,"O iterador '%.*s' nao e utilizado dentro do laco.",(int)d->name_length,d->name);break;case ANALYSIS_ONLY_ASSIGNED:fprintf(out,"'%.*s' recebe valores, mas nenhum deles e utilizado.",(int)d->name_length,d->name);break;case ANALYSIS_OVERWRITTEN_VALUE:fprintf(out,"O valor anterior de '%.*s' e substituido antes de ser utilizado.",(int)d->name_length,d->name);break;case ANALYSIS_UNREACHABLE:fputs("Este codigo nunca sera executado porque existe um 'retorne' antes dele.",out);break;case ANALYSIS_CONSTANT_CONDITION:fprintf(out,"Esta condicao e sempre %s.",d->boolean_value?"verdadeira":"falsa");break;case ANALYSIS_EMPTY_FOR:fputs("Este laco executara zero vezes porque o inicio e maior que o fim.",out);break;case ANALYSIS_SHADOWING:fprintf(out,"'%.*s' oculta temporariamente um nome de um escopo externo; isto e valido, mas pode causar confusao.",(int)d->name_length,d->name);break;case ANALYSIS_NATIVE_SHADOWING:fprintf(out,"'%.*s' oculta temporariamente a funcao nativa de mesmo nome.",(int)d->name_length,d->name);break;case ANALYSIS_UNDEFINED_NAME:fprintf(out,"O nome '%.*s' nao foi definido.",(int)d->name_length,d->name);break;case ANALYSIS_SELF_ASSIGNMENT:fprintf(out,"A atribuicao '%.*s = %.*s' nao altera o valor.",(int)d->name_length,d->name,(int)d->name_length,d->name);break;}}
static void render_one(FILE *out,const Source *source,const AnalysisDiagnostic *d){size_t line_start,line_end,marker,index,length;fprintf(out,"\n%s %s em %s:%zu:%zu\n\n",severity_name(d->severity),category_name(d->code),source->name,d->span.start.line,d->span.start.column);line_start=d->span.start.offset<=source->length?d->span.start.offset:source->length;while(line_start>0U&&source->bytes[line_start-1U]!='\n')line_start--;line_end=d->span.start.offset<=source->length?d->span.start.offset:source->length;while(line_end<source->length&&source->bytes[line_end]!='\n'&&source->bytes[line_end]!='\r')line_end++;fwrite(source->bytes+line_start,1U,line_end-line_start,out);fputc('\n',out);marker=d->span.start.offset-line_start;for(index=0U;index<marker;index++)fputc(source->bytes[line_start+index]=='\t'?'\t':' ',out);length=d->span.end.offset>d->span.start.offset?d->span.end.offset-d->span.start.offset:1U;if(length>line_end-(line_start+marker))length=line_end-(line_start+marker);if(length==0U)length=1U;for(index=0U;index<length;index++)fputc('^',out);fputs("\n\n",out);message(out,d);fputc('\n',out);if(d->suggestion!=NULL)fprintf(out,"\nDica:\nVoce quis dizer '%.*s'?\n",(int)d->suggestion_length,d->suggestion);}
void analyzer_render(FILE *output,const Source *source,const AnalysisResult *r){size_t i;if(output==NULL||source==NULL||r==NULL)return;fprintf(output,"Analisando: %s\n",source->name);for(i=0U;i<r->count;i++)render_one(output,source,&r->diagnostics[i]);fputs("\nEstrutura:\n",output);fprintf(output,"  variaveis: %zu\n  constantes: %zu\n  funcoes: %zu\n  condicoes: %zu\n  lacos enquanto: %zu\n  lacos para: %zu\n  listas: %zu\n",r->metrics.variables,r->metrics.constants,r->metrics.functions,r->metrics.conditions,r->metrics.while_loops,r->metrics.for_loops,r->metrics.lists);fprintf(output,"\nResumo:\n  %zu aviso(s)\n  %zu erro(s)\n  %zu informacao(oes)\n",r->warnings,r->errors,r->information);if(r->count==0U)fputs("\nAnalise concluida.\nNenhum problema educacional encontrado.\n",output);}
